import json
import os
import subprocess
import sys
from pathlib import Path

from app.services import users

_PROJECT_ROOT = Path(__file__).resolve().parents[2]
_DATA_DIR = _PROJECT_ROOT / "data"


def _clean_relative_path(raw: object) -> str | None:
    """Return ``raw`` when it is a safe path relative to ``data/``, else ``None``."""
    if not isinstance(raw, str) or raw == "":
        return None
    if os.path.isabs(raw):
        return None
    segments = raw.split("/")
    if any(segment in ("", ".", "..") for segment in segments):
        return None
    return "/".join(segments)


def handle_get_user(params: dict) -> tuple[int, dict]:
    raw = params.get("id")
    if not isinstance(raw, str) or not raw.isdigit():
        return 400, {"error": "invalid id"}
    user = users.get_user(int(raw))
    if user is None:
        return 404, {"error": "not found"}
    return 200, user


def handle_file_digest(params: dict) -> tuple[int, dict]:
    path = _clean_relative_path(params.get("path"))
    if path is None:
        return 400, {"error": "invalid path"}
    try:
        exists = (_DATA_DIR / path).is_file()
    except (OSError, ValueError):
        exists = False
    if not exists:
        return 404, {"error": "not found"}
    result = subprocess.run(
        [sys.executable, "scripts/digest.py", "--file", f"data/{path}"],
        cwd=_PROJECT_ROOT,
        capture_output=True,
        text=True,
        check=False,
    )
    if result.returncode != 0:
        return 404, {"error": "not found"}
    return 200, json.loads(result.stdout)
